param(
    [string]$SourcePath="$PSScriptRoot\..\assets\concept\HOUND\VLR-03_HOUND_source.jpg",
    [string]$CleanupSourcePath="$PSScriptRoot\..\assets\concept\HOUND\VLR-03_HOUND_cleanup_source.png",
    [string]$OutputDirectory="$PSScriptRoot\..\assets\enemies\sector_07\hound\sprites"
)
$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Drawing
$a=[Drawing.Bitmap].Assembly.Location;$r=Split-Path $a;$refs=@($a,(Join-Path $r 'System.Drawing.Primitives.dll'),(Join-Path $r 'System.Private.Windows.GdiPlus.dll'),(Join-Path $r 'System.Private.Windows.Core.dll'),(Join-Path $r 'System.Private.CoreLib.dll'),(Join-Path $r 'System.Runtime.dll'),(Join-Path $r 'System.Collections.dll'))
Add-Type -ReferencedAssemblies $refs -TypeDefinition @'
using System;using System.Collections;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.IO;
public static class HoundConceptBuilder{
 class C{public int Id,N,X0,Y0,X1,Y1;public double CX{get{return(X0+X1)/2.0;}}}
 static bool Bg(Color c){int hi=Math.Max(c.R,Math.Max(c.G,c.B)),lo=Math.Min(c.R,Math.Min(c.G,c.B));return hi<=20&&hi-lo<=7;}
 static Bitmap Cut(Bitmap s,Rectangle q){var b=s.Clone(q,PixelFormat.Format32bppArgb);int w=b.Width,h=b.Height;var v=new bool[w*h];var z=new int[w*h];int p=0,n=0;for(int x=0;x<w;x++)foreach(int y in new[]{0,h-1}){int i=y*w+x;if(!v[i]&&Bg(b.GetPixel(x,y))){v[i]=true;z[n++]=i;}}for(int y=0;y<h;y++)foreach(int x in new[]{0,w-1}){int i=y*w+x;if(!v[i]&&Bg(b.GetPixel(x,y))){v[i]=true;z[n++]=i;}}int[] dx={1,-1,0,0},dy={0,0,1,-1};while(p<n){int i=z[p++],x=i%w,y=i/w;b.SetPixel(x,y,Color.Transparent);for(int d=0;d<4;d++){int xx=x+dx[d],yy=y+dy[d];if(xx<0||yy<0||xx>=w||yy>=h)continue;int j=yy*w+xx;if(!v[j]&&Bg(b.GetPixel(xx,yy))){v[j]=true;z[n++]=j;}}}for(int y=0;y<h;y++)for(int x=0;x<w;x++){var c=b.GetPixel(x,y);int hi=Math.Max(c.R,Math.Max(c.G,c.B));b.SetPixel(x,y,c.A==0||hi<10?Color.Transparent:Color.FromArgb(255,c.R,c.G,c.B));}return b;}
 static C[] Parts(Bitmap b,int count,out int[] labels){int w=b.Width,h=b.Height;labels=new int[w*h];int[] q=new int[w*h],dx={-1,0,1,-1,1,-1,0,1},dy={-1,-1,-1,0,0,1,1,1};var all=new ArrayList();int id=0;for(int sy=0;sy<h;sy++)for(int sx=0;sx<w;sx++){int st=sy*w+sx;if(labels[st]!=0||b.GetPixel(sx,sy).A==0)continue;id++;int a=0,e=0;q[e++]=st;labels[st]=id;var c=new C{Id=id,X0=sx,X1=sx,Y0=sy,Y1=sy};while(a<e){int k=q[a++],x=k%w,y=k/w;c.N++;c.X0=Math.Min(c.X0,x);c.X1=Math.Max(c.X1,x);c.Y0=Math.Min(c.Y0,y);c.Y1=Math.Max(c.Y1,y);for(int d=0;d<8;d++){int xx=x+dx[d],yy=y+dy[d];if(xx<0||yy<0||xx>=w||yy>=h)continue;int j=yy*w+xx;if(labels[j]==0&&b.GetPixel(xx,yy).A>0){labels[j]=id;q[e++]=j;}}}if(c.N>250)all.Add(c);}var take=new C[count];var used=new bool[all.Count];for(int k=0;k<count;k++){int best=-1;for(int i=0;i<all.Count;i++)if(!used[i]&&(best<0||((C)all[i]).N>((C)all[best]).N))best=i;if(best<0)throw new InvalidDataException("Not enough HOUND silhouettes");used[best]=true;take[k]=(C)all[best];}for(int i=0;i<count-1;i++)for(int j=i+1;j<count;j++)if(take[j].CX<take[i].CX){var t=take[i];take[i]=take[j];take[j]=t;}return take;}
 static Rectangle Bounds(Bitmap b){int x0=b.Width,y0=b.Height,x1=-1,y1=-1;for(int y=0;y<b.Height;y++)for(int x=0;x<b.Width;x++)if(b.GetPixel(x,y).A>0){x0=Math.Min(x0,x);x1=Math.Max(x1,x);y0=Math.Min(y0,y);y1=Math.Max(y1,y);}if(x1<0)throw new InvalidDataException("Empty HOUND frame");return Rectangle.FromLTRB(x0,y0,x1+1,y1+1);}
 static double BodyCenter(Bitmap f,Rectangle b){int[] cols=new int[b.Width];for(int y=b.Top;y<b.Bottom;y++)for(int x=b.Left;x<b.Right;x++)if(f.GetPixel(x,y).A>0)cols[x-b.Left]++;int win=Math.Min(b.Width,Math.Max(40,b.Height)),sum=0;for(int x=0;x<win;x++)sum+=cols[x];int best=sum,start=0;for(int x=win;x<cols.Length;x++){sum+=cols[x]-cols[x-win];if(sum>best){best=sum;start=x-win+1;}}return b.Left+start+win/2.0;}
 public static void Build(string src,string dst,int sy,int sh,int[] map,bool death){using(var sheet=new Bitmap(src)){const int sourceCount=6,fw=160;var f=new Bitmap[sourceCount];var b=new Rectangle[sourceCount];var center=new double[sourceCount];if(!death){using(var row=Cut(sheet,new Rectangle(0,sy,sheet.Width,sh))){int[] labels;var parts=Parts(row,sourceCount,out labels);for(int i=0;i<sourceCount;i++){var c=parts[i];f[i]=new Bitmap(c.X1-c.X0+1,c.Y1-c.Y0+1,PixelFormat.Format32bppArgb);for(int y=c.Y0;y<=c.Y1;y++)for(int x=c.X0;x<=c.X1;x++)if(labels[y*row.Width+x]==c.Id)f[i].SetPixel(x-c.X0,y-c.Y0,row.GetPixel(x,y));b[i]=Bounds(f[i]);center[i]=BodyCenter(f[i],b[i]);}}}else for(int i=0;i<sourceCount;i++){int x0=(int)Math.Floor((double)i*sheet.Width/sourceCount),x1=(int)Math.Floor((double)(i+1)*sheet.Width/sourceCount);f[i]=Cut(sheet,new Rectangle(x0,sy,x1-x0,sh));b[i]=Bounds(f[i]);center[i]=BodyCenter(f[i],b[i]);}
 int[] hs=new int[sourceCount];int mw=1;for(int i=0;i<sourceCount;i++){hs[i]=b[i].Height;mw=Math.Max(mw,b[i].Width);}var sorted=(int[])hs.Clone();Array.Sort(sorted);double scale=Math.Min(76.0/(death?hs[0]:sorted[3]),156.0/mw);using(var atlas=new Bitmap(map.Length*fw,96,PixelFormat.Format32bppArgb))using(var g=Graphics.FromImage(atlas)){g.Clear(Color.Transparent);g.CompositingMode=CompositingMode.SourceCopy;g.InterpolationMode=InterpolationMode.NearestNeighbor;g.PixelOffsetMode=PixelOffsetMode.Half;for(int i=0;i<map.Length;i++){int k=map[i];var q=b[k];int tw=Math.Max(1,(int)Math.Round(q.Width*scale)),th=Math.Max(1,(int)Math.Round(q.Height*scale));int lx=fw/2-(int)Math.Round((center[k]-q.Left)*scale);lx=Math.Max(2,Math.Min(fw-2-tw,lx));g.DrawImage(f[k],new Rectangle(i*fw+lx,95-th,tw,th),q,GraphicsUnit.Pixel);}for(int i=0;i<sourceCount;i++)f[i].Dispose();g.Dispose();for(int y=0;y<atlas.Height;y++)for(int x=0;x<atlas.Width;x++){var c=atlas.GetPixel(x,y);atlas.SetPixel(x,y,c.A<128?Color.Transparent:Color.FromArgb(255,c.R,c.G,c.B));}Directory.CreateDirectory(Path.GetDirectoryName(dst));atlas.Save(dst,ImageFormat.Png);}}}
 public static void Replace(string atlasPath,string cleanupPath,int firstFrame,int[] boxes){string tmp=atlasPath+".tmp.png";using(var atlas=new Bitmap(atlasPath))using(var source=new Bitmap(cleanupPath))using(var g=Graphics.FromImage(atlas)){const int fw=160,fh=96;g.CompositingMode=CompositingMode.SourceCopy;g.InterpolationMode=InterpolationMode.NearestNeighbor;g.PixelOffsetMode=PixelOffsetMode.Half;for(int i=0;i<boxes.Length/4;i++){var crop=source.Clone(new Rectangle(boxes[i*4],boxes[i*4+1],boxes[i*4+2],boxes[i*4+3]),PixelFormat.Format32bppArgb);var q=Bounds(crop);double scale=Math.Min(92.0/q.Height,156.0/q.Width);int tw=Math.Max(1,(int)Math.Round(q.Width*scale)),th=Math.Max(1,(int)Math.Round(q.Height*scale));int frame=firstFrame+i;g.FillRectangle(Brushes.Transparent,frame*fw,0,fw,fh);g.DrawImage(crop,new Rectangle(frame*fw+(fw-tw)/2,fh-1-th,tw,th),q,GraphicsUnit.Pixel);crop.Dispose();}g.Dispose();for(int y=0;y<atlas.Height;y++)for(int x=0;x<atlas.Width;x++){var c=atlas.GetPixel(x,y);atlas.SetPixel(x,y,c.A<96?Color.Transparent:Color.FromArgb(255,c.R,c.G,c.B));}atlas.Save(tmp,ImageFormat.Png);}File.Copy(tmp,atlasPath,true);File.Delete(tmp);}
}
'@
$rows=[ordered]@{
 idle=@(0,115,@(0,1,2,3,4,5),$false);walk_prowl=@(115,120,@(0,1,2,3,4,5),$false);charge=@(235,115,@(0,1,2,3,4),$false);pounce=@(350,125,@(0,1,2,3,4,5),$false);claw_combo=@(475,120,@(0,1,2,3,4,5),$false);energy_burst=@(595,120,@(0,1,2,3,4,5,4,5),$false);hit=@(595,120,@(0,2,4),$false);death=@(715,138,@(0,1,2,3,4,5,5,5),$true)
}
$src=[IO.Path]::GetFullPath($SourcePath);$cleanup=[IO.Path]::GetFullPath($CleanupSourcePath);$out=[IO.Path]::GetFullPath($OutputDirectory);foreach($e in $rows.GetEnumerator()){$v=$e.Value;$dst=Join-Path $out ($e.Key+'.png');[HoundConceptBuilder]::Build($src,$dst,[int]$v[0],[int]$v[1],[int[]]$v[2],[bool]$v[3]);Write-Output("BUILT hound/{0}: {1}x96"-f$e.Key,($v[2].Count*160))}

# Authored cleanup poses replace only the documented source gaps. Runtime frame
# counts, frame canvases, pivots, and all gameplay-owned collision stay unchanged.
[HoundConceptBuilder]::Replace((Join-Path $out 'energy_burst.png'),$cleanup,6,@(1493,152,216,118,1720,147,244,123))
[HoundConceptBuilder]::Replace((Join-Path $out 'hit.png'),$cleanup,0,@(556,352,256,130,843,343,254,145,1123,367,235,123))
[HoundConceptBuilder]::Replace((Join-Path $out 'death.png'),$cleanup,6,@(1371,593,292,118,1667,611,296,99))
Write-Output 'APPLIED HOUND cleanup poses: energy_burst[6..7], hit[0..2], death[6..7]'
